#include <stdio.h>

int main(void) {
    int N;
    scanf("%d", &N);

    int pos[100000];
    int m = 0;

    for (int i = 1; i <= N; i++) {
        int x;
        scanf("%d", &x);
        if (x == 1) {
            pos[m++] = i;
        }
    }

    long long ans = 0;

    for (int j = 0; j < m; j++) {
        int prev = (j == 0) ? 0 : pos[j - 1];
        int next = (j + 1 == m) ? N + 1 : pos[j + 1];

        ans += (long long)(pos[j] - prev) * (next - pos[j]);
    }

    printf("%lld\n", ans);
    return 0;
}
